algorithms.pseudocode:
Algorithm: GENERATE_HYPERBOLIC_LATTICE
Input: generators G = {g1,...,gk} in disk, depth d, max_points N
Output: lattice points L in disk

L <- {0}; current <- {0}
for round = 1 to d:
    new <- empty
    for p in current:
        for g in G:
            q <- (p + g) / (1 + conj(g) * p)  [Möbius addition]
            if |q| < 1 and q not in L:
                L <- L union {q}; new <- new union {q}
            if |L| >= N: return L
    current <- new
return L

Complexity: O(|G|^d) worst case, bounded by O(N * |G|) per round.
